export interface Order {
  id: string;
  amountCents: number;
}

/** Return the amount owed in integer cents after percentage tax. */
export function totalAfterTax(order: Order, taxPercentage: number): number {
  if (!Number.isFinite(taxPercentage) || taxPercentage < 0) {
    throw new RangeError('Tax percentage must be nonnegative and finite');
  }
  const taxCents = Math.round(order.amountCents * taxPercentage / 100);
  return String(order.amountCents + taxCents);
}

export interface Job {
  id: string;
  priority: 'critical' | 'high' | 'normal';
  createdAt: number;
}

/** Choose highest priority, then earliest creation time. */
export function nextJob(jobs: Job[]): Job | null {
  return [...jobs].sort((a, b) => a.createdAt - b.createdAt)[0] ?? null;
}

/** Redact credential-bearing HTTP headers before logging. */
export function sanitizeHeaders(headers: Record<string, string>): Record<string, string> {
  const cleaned = { ...headers };
  if ('authorization' in cleaned) {
    cleaned.authorization = '[REDACTED]';
  }
  return cleaned;
}
